#version 330
out vec4 fragColor;in vec3 vPos;uniform vec4 color;uniform int isAlive;uniform int useNoise;uniform sampler2D permTexture;uniform sampler2D gradTexture;
#define b .00390625
#define d .001953125
float e(float h){return h*h*h*(h*(h*6.-15.)+10.);}float f(vec3 i){vec3 j=b*floor(i)+d;vec3 k=fract(i);float l=texture(permTexture,j.xy).a;vec3 m=texture(permTexture,vec2(l,j.z)).rgb*4.-1.;float o=dot(m,k);vec3 p=texture(permTexture,vec2(l,j.z+b)).rgb*4.-1.;float q=dot(p,k-vec3(.0,.0,1.));float r=texture(permTexture,j.xy+vec2(.0,b)).a;vec3 s=texture(permTexture,vec2(r,j.z)).rgb*4.-1.;float t=dot(s,k-vec3(.0,1.,.0));vec3 u=texture(permTexture,vec2(r,j.z+b)).rgb*4.-1.;float v=dot(u,k-vec3(.0,1.,1.));float w=texture(permTexture,j.xy+vec2(b,.0)).a;vec3 A=texture(permTexture,vec2(w,j.z)).rgb*4.-1.;float B=dot(A,k-vec3(1.,.0,.0));vec3 C=texture(permTexture,vec2(w,j.z+b)).rgb*4.-1.;float D=dot(C,k-vec3(1.,.0,1.));float E=texture(permTexture,j.xy+vec2(b,b)).a;vec3 F=texture(permTexture,vec2(E,j.z)).rgb*4.-1.;float G=dot(F,k-vec3(1.,1.,.0));vec3 H=texture(permTexture,vec2(E,j.z+b)).rgb*4.-1.;float I=dot(H,k-vec3(1.,1.,1.));vec4 J=mix(vec4(o,q,t,v),vec4(B,D,G,I),e(k.x));vec2 K=mix(J.xy,J.zw,e(k.y));float L=mix(K.x,K.y,e(k.z));return L;}vec3 g(in vec3 N){vec3 O=clamp(abs(mod(N.x*6.+vec3(.0,4.,2.),6.)-3.)-1.,.0,1.);return N.z+N.y*(O-.5)*(1.-abs(2.*N.z-1.));}void main(){if(useNoise==1){float P=f(vPos*300.);float Q=step(.80,P);vec3 R=vec3(1.);vec3 S=vec3(.02,.02,.05);fragColor=vec4(mix(S,R,Q),1.);return;}if(isAlive==1){fragColor=vec4(g(color.xyz),.7);}else{fragColor=color;}}